\begin{equation}
		\label{problem:original}
		\min_{x\in\cX}~F(x) := \Expu{\xi \sim \cD}{f(x, \xi)}, 
	\end{equation}

	where $\cX $ is a closed convex subset of $\R^d$, $\xi$ is a random variable following an unknown distribution $\cD$, and $F(\cdot)$ is possibly non-convex in $x$. Our central structural assumption about \eqref{problem:original} is that it admits a \textit{convex reformulation} of the form


\begin{equation}
		\label{problem:reformulation}
		\min_{u\in \cU}~H(u):= F(c^{-1}(u)), %\text{with  } g(x) = u,
	\end{equation}

	Throughout, we denote by $\ve{\cdot}{\cdot}$ the inner product in $\R^d$ along with its induced Euclidean norm $\norm{\cdot}$. For a real valued matrix $A\in \R^{m\times n}$, we denote by $\opnorm{\cdot}$ its operator norm, i.e.,  $\opnorm{A} := \max_{\norm{x}\leq 1}\norm{A x}$. {\color{black} We denote the interior and the boundary of $\cX$ as $\operatorname{int} \cX$ and $\partial \cX$ respectively.} %For any map $c: \cX \rightarrow \cU$, we say $c$ is $L$-Lipschitz continuous on the set $\cX \subset \R^d$ if there exists a constant $L < +\infty$ such that for all $x, y\in \cX$ it holds $\norm{c(x) - c(y)} \leq L \norm{x - y}. $
    %We denote $\text{Ker}( A ) := \left\{ x \in \R^n | A x = 0 \right\} $.
	The map $c: \cX \rightarrow \cU$ is called invertible if there exists a map $c^{-1}: \cU \rightarrow \cX$ (called inverse) such that $c^{-1}(c(x)) = x$ for any $x \in \cX$ and $c( c^{-1}(u) ) = u$ for any $u \in \cU$. For any $u, v\in\cU$ and any $\lambda\in[0,1]$, if  $(1-\lambda) u + \lambda v \in \cU$, we say $\mathcal{U}$ is convex. We denote the diameter of $\cU$ as $D_{\cU}:= \sup_{u, v\in \cU}\pnorm{u - v}$.


A function $F: \cX \rightarrow\R \cup \{+\infty\}$ is $\ell$-weakly convex ($\ell$-WC) if for any fixed $y\in \cX$, $F_{\ell}(x,y) := F(x) + \frac{\ell}{2} \, \sqnorm{x- y}$ is convex in $x \in \cX$.
If $x\notin \cX$, we assign $F(x) = +\infty$. The (Fr\'echet) sub-differential of $F$ at $x\in \cX$ is $\partial F(x) := \left\{g \in \mathbb{R}^d \mid  F(y) \geq F(x)+\langle g, y-x\rangle+o(\|y-x\|), \forall y \in \R^d  \right\}.$ The elements $g \in \partial F(x)$ are called sub-gradients of $F$ at $x$, see \cite{davis2019proximally} for alternative equivalent definitions of the sub-differential set for $\ell$-WC functions. A differentiable function $F: \cX \rightarrow \R$ is $L$-smooth on $\cX \subset \R^d$ if its gradient is $L$-Lipschitz continuous on the set $\cX$, i.e., it holds $\norm{\nabla F(x) - \nabla F(y)} \leq L \norm{x - y}$ for all $x, y\in \cX$. For a convex set $\cX \subset \R^d$, the projection of a point $y\in \R^d$ onto $\cX$ is  $\Pi_{\cX}(y) := \argmin_{x\in\cX}\norm{y - x}$. We denote $\delta_{\cX}$ as the indicator function of a set $\cX \subset \R^d$ and define $\delta_{\cX}(x)  = 0$ if $x\in \cX$ and $\delta_{\cX}(x)  = +\infty$ otherwise. 


    We define by $\cX^* \subset \cX$ the set of optimal points of $\min_{x\in\cX} F(x)$ and by $F^*$ its optimal value. A point $\bar{x} \in \cX$ is called a stationary point of a weakly convex function $F: \cX \rightarrow \R$ if $0 \in \partial (F +  \delta_{\cX})(\bar{x})$.


\begin{equation}
		\label{problem:original_composition}
		\min_{x\in\cX}~F(x) := H(c(x)) . 
	\end{equation}

\begin{definition}
The  above problem is called {hidden convex} with modulus $\mu_c>0, \mu_H\geq 0$ (or function $F$ is hidden convex on $\cX$) if its components satisfy the following underlying conditions. 
	\begin{enumerate}%[ref=\theenumi{}~(\alph*)]
		%\item The set $\cX \subset \R^d $ is closed and convex. \label{ass:convex_cX}
		\myitem{C.1}\label{C1} The domain $\mathcal{U}=c(\mathcal{X})$ is convex, the function $H: \cU \rightarrow \R$ satisfies that for all $u, v \in \cU$ and $ \lambda \in [0,1]$, 
  \begin{equation}\label{assumption:H_conv}
  	H( (1-\lambda)u + \lambda v ) \leq  (1- \lambda) H(u) +  \lambda  H(v)  -   \fr{(1-\lambda)\lambda \mu_H}{2} \sqpnorm{ u - v }, 
  \end{equation}
  and \eqref{problem:reformulation} admits a solution $u^* \in \cU$.  %\label{ass:convex_H} 

		\myitem{C.2} The map $c: \cX \rightarrow \cU$ is invertible. There exists $\mu_c>0$ such that  for all $x, y \in \cX$ it holds  \label{C2}
		\begin{equation}\label{assumption:g_inv}
			\pnorm{c(x) - c(y) } \geq \mu_c \pnorm{x - y }.
		\end{equation}
		%\item The function $F: \cX \rightarrow \R$ is differentiable on $\cX$ and its gradient $\nabla F(x)$ is $L$-Lipschitz continuous. 
	\end{enumerate}
	%\IF{Check if A.2. is connected to metric subregularity condition from the works of Russel Luke. }
	%\end{assumption}
In particular, if $\mu_H>0$, we say the above problem is {$(\mu_c,\mu_H)$-hidden strongly convex}.  
\end{definition}

    \begin{enumerate}
    \myitem{A.1'}\label{A1'} The function $F: \cX \rightarrow \R$ is differentiable on a closed, convex set $\cX$ and its gradient $\nabla F(x)$ is $L$-Lipschitz continuous. 

    \myitem{A.2'}\label{A2'} We have access to an unbiased stochastic gradient oracle with bounded variance $\sigma > 0$, i.e. for any $x\in \cX$: 
	$\Exp{\nabla f(x,\xi)} = \nabla F(x)$, and 
	$$\Exp{\sqnorm{\nabla f(x,\xi) - \nabla F(x)}} \leq \sigma^2, $$where expectations are with respect to the random variable $\xi \sim \cD$.  
    \end{enumerate}


\begin{align}
	%\boxed{ 
		x^{t+1} = \Pi_{\mathcal{X}}(x^t-\stepsize \, g^t) , \qquad  \label{eq:PSGDM_x_upd}
		g^{t+1} = (1-\momentum) \, g^{t} + \momentum \, \nabla f(x^{t+1}, \xi^{t+1}) . 
		%} %\label{eq:PSGDM_g_upd} 
\end{align}

Let $x^* \in \cX^*$, for any $x^t \in \cX$, we define the Lyapunov function
\begin{equation}\label{eq:Lyapunov_HB}
	\Lambda_t^{HB} := \Exp{ F(x^t) - F(x^*) + \frac{\stepsize}{\momentum} \sqnorm{g^t - \nabla F(x^t)} } .
\end{equation}

