\begin{proposition}\label{prop:HC}
		Let $F(\cdot)$ be hidden convex with $\mu_c>0, \mu_H\geq0$. For any $\alpha \in [0,1]$, $x^* \in \cX^*$ and $x\in \cX$ , define $x_{\alpha} := c^{-1} \rb{(1-\alpha) c(x) + \alpha c(x^*)}$. Then
		\begin{eqnarray}\label{prop:F_x_alpha_strong_conv}
			F(x_{\alpha}) \leq  (1- \alpha) F(x) + \alpha  F(x^*)  -   \fr{(1-\alpha) \alpha  \mu_H}{2}  \sqpnorm{c(x) - c(x^*) } ,
		\end{eqnarray}	\begin{eqnarray}\label{prop:x_alpha_x_bound}
			\pnorm{ x_{\alpha}-x } \leq \fr{\alpha }{\mu_c} \pnorm{c(x) - c(x^*) } .
		\end{eqnarray}

	\end{proposition}

\begin{proof}
		%\textbf{Part I: \eqref{prop:F_x_alpha_strong_conv}.} 
		By the (strong) convexity of $H(\cdot)$ and the convexity of $\cU$, we have
		\begin{eqnarray*}
			F(x_{\alpha}) &=& F( c^{-1} \rb{(1-\alpha) c(x) + \alpha c(x^*)} ) \\
			& = & H( (1-\alpha) c(x) + \alpha c(x^*) ) \\ 
			& \leq  &  (1-\alpha) H( c(x) ) + \alpha H( c(x^*) ) -   \fr{(1-\alpha) \alpha  \mu_H}{2} \sqpnorm{c(x) - c(x^*) }\\
			& =  &  (1- \alpha) F(x)  +  \alpha F(x^*) -  \fr{(1-\alpha)  \alpha   \mu_H}{2} \sqpnorm{c(x) - c(x^*) }.
		\end{eqnarray*}
  where the inequality uses the fact that $\cU$ is a convex set and that $(1-\alpha) c(x) + \alpha c(x^*) \in \cU$ for any $x \in \cX$. By definition of $x_{\alpha}$ and \eqref{assumption:g_inv}, we derive
		$$
		\pnorm{ x_{\alpha}-x } = \pnorm{ c^{-1} \rb{(1-\alpha) c(x) + \alpha c(x^*)} - c^{-1}(c(x)) } \leq \fr{1}{\mu_c} \pnorm{\alpha(c(x) - c(x^*)) } .
		$$
		\end{proof}

\begin{lemma}[Lemma 2 in \cite{fatkhullin2023momentum}]\label{le:key_HB_recursion}
		Let $\momentum \in (0,1]$ and $g^t$ be updated via \eqref{eq:PSGDM_x_upd}. Then
		\begin{eqnarray}\notag %\label{eq:key_HB_recursion}
			\Exp{ \sqnorm{g^{t+1} - \nabla F(x^{t+1})} }  \leq (1 - \momentum) \Exp{ \sqnorm{  g^{t} - \nabla F(x^{t}) } }  + \fr{3 L^2}{\momentum} \Exp{ \sqnorm{  x^{t} - x^{t+1}  } } + \momentum^2 \sigma^2 .
		\end{eqnarray}
	\end{lemma}

\begin{theorem}\label{le:descent_HB_HC}
	Suppose that \ref{C1}, \ref{C2}, \ref{A1'}, \ref{A2'} hold with $\mu_H\geq0$, and the step-size in \eqref{eq:PSGDM_x_upd} satisfies $\stepsize \leq 1 / L$. For any $\alpha \in [0, 1] $, it holds that
	\begin{eqnarray}\label{eq:descent_HC}
		F(x^{t+1})  &\leq&  (1- \alpha) F(x^t) +  \alpha F(x^*)  + \rb{  \fr{ \alpha^{2} }{ \mu_c^2 \stepsize } -  \fr{(1-\alpha) \alpha  \mu_H}{2} } \sqnorm{ c(x^t) - c(x^*) },  \notag \\
		&& \qquad - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t } + \frac{\stepsize}{2} \sqnorm{g^t - \nabla F(x^t) } .
	\end{eqnarray}
\end{theorem}

\begin{proof}
	By the update rule of $x^{t+1}$ and following the standard descent inequality (cf. \cref{le:bregman_properties_optimality}), we have for any $z \in \cX$ that
	\begin{eqnarray}\label{eq:projection_upd}
		\langle g^t , x^{t+1} - z \rangle  + \frac{1}{2\stepsize} \sqnorm{ x^{t+1} - x^t} \leq \frac{1}{2\stepsize} \sqnorm{ z - x^t } -\frac{1}{2\stepsize} \sqnorm{ z - x^{t+1} }  .
	\end{eqnarray}

	By the smoothness of $F(\cdot)$, we derive
	\begin{eqnarray}
		F(x^{t+1}) &\leq& F(x^t) + \langle \nabla F(x^t), x^{t+1}- x^t \rangle + \fr{L}{2} \sqnorm{x^{t+1}-x^t } \notag \\
		&=& F(x^t) + \langle g^t, x^{t+1}- x^t \rangle + \fr{1}{2 \stepsize } \sqnorm{x^{t+1}-x^t } \notag \\
		&& \qquad  + \langle \nabla F(x^t) - g^t , x^{t+1}- x^t \rangle - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t } \notag \\
		&\overset{(i)}{\leq}&  F(x^t) + \langle g^t, z - x^t \rangle + \fr{1}{2 \stepsize } \sqnorm{z - x^t } - \fr{1}{2 \stepsize } \sqnorm{z - x^{t+1} }  \notag \\
		&& \qquad  + \langle \nabla F(x^t) - g^t , x^{t+1}- x^t \rangle - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t }   \notag \\
		& { = } & F(x^t) + \langle \nabla F(x^t), z - x^t \rangle + \fr{1}{2 \stepsize } \sqnorm{ z - x^t } - \fr{1}{2 \stepsize } \sqnorm{ z - x^{t+1} }  \notag \\  
		&& \qquad + \langle \nabla F(x^t) - g^t , x^{t+1}- z \rangle - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t } \notag  \\
		& \overset{(ii)}{ \leq } & F(x^t) + \langle \nabla F(x^t), z - x^t \rangle + \fr{1}{2 \stepsize } \sqnorm{z - x^t }   + \frac{\stepsize}{2} \sqnorm{g^t - \nabla F(x^t) }  \notag \\
		&& \qquad - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t } \notag  \\
		&\overset{(iii)}{\leq}& F(z) + \fr{L}{2}\sqnorm{ z - x^t } + \fr{1}{2 \stepsize } \sqnorm{z - x^t }  + \frac{\stepsize}{2} \sqnorm{g^t - \nabla F(x^t) }  \notag \\
		&& \qquad - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t } \notag  ,
	\end{eqnarray}
	where $(i)$ follows from \eqref{eq:projection_upd}, $(ii)$ holds by Young's inequality, i.e., $\langle a, b\rangle \leq \frac{\stepsize}{2}\sqnorm{a} + \frac{1}{2 \stepsize} \sqnorm{b} $ with $a = \nabla F(x^t) - g^t$, $b = x^{t+1} - z $, $(iii)$ holds by the smoothness of $F(\cdot)$, i.e., $-\frac{L}{2}\sqnorm{z - x^t } \leq F(x^t) - F(z) - \langle \nabla F(x^t) , z - x^t \rangle $. 

	We are now ready to utilize the properties of hidden convex functions to bound $F(z)$ and $\sqnorm{z - x^t}$ for some specific choice of $z \in \cX$. We select $z := x_{\alpha}^t = c^{-1}((1-{\alpha})c(x^t)+ {\alpha} c(x^*)) \in \cX$, for some $\alpha \in [0,1]$, and $x^* \in \cX^* $. By \Cref{prop:HC}, we have for $\mu_H \geq 0$, 
	$$
	F(z) \leq (1- \alpha) F(x^t) +  \alpha F(x^*) -    \fr{(1-\alpha) \alpha  \mu_H}{2} \sqnorm{ c(x^t) - c(x^*) } ,
	$$
 and
	$$
	\sqnorm{z - x^t } \leq \fr{ \alpha^{2} }{ \mu_c^2  } \sqnorm{ c(x^t) - c(x^*) }.
	$$
	Combining the three inequalities above  and utilizing the assumption $\stepsize \leq 1/L$, we complete the proof.
	%\begin{eqnarray}F(x^{t+1})  &\leq&  (1- \alpha) F(x^t) +  \alpha F(x^*)  + \rb{  \fr{ \alpha^{2} }{ \mu_c^2 \stepsize } -   \fr{ (1-\alpha)\alpha   \mu_H}{2} } \sqnorm{ c(x^t) - c(x^*) }  \notag \\ && \qquad - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \sqnorm{x^{t+1}-x^t } + \frac{\stepsize}{2} \sqnorm{g^t - \nabla F(x^t) } . \end{eqnarray}
\end{proof}

\begin{proof} 
	%\textbf{Step I. Descent-like lemma for hidden convex objectives.} We start the proof by using our descent like Lemma~\ref{le:descent_HB_HC}, which guarantees that for any $\stepsize \leq 1/L$
	By \Cref{le:descent_HB_HC}, subtracting $F(x^*)$ from both sides of  \eqref{eq:descent_HC}, setting $\mu_H=0$, and taking the expectation, we have for any $\stepsize \leq 1/L$ that
	\begin{eqnarray*}
		\Exp{F(x^{t+1}) - F(x^*)}  &\leq&  (1-  \alpha) \Exp{ F(x^t)  - F(x^*) }  +  \fr{ \alpha^{2} }{ \mu_c^2 \stepsize } \Exp{ \sqnorm{ c(x^t) - c(x^*) } } \notag \\
		&& \qquad - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \Exp{\sqnorm{x^{t+1}-x^t }} + \frac{\stepsize}{2} \Exp{\sqnorm{g^t - \nabla F(x^t) }} \\
		&\leq&  (1-  \alpha) \Exp{ F(x^t)  - F(x^*) }  +  \fr{ \alpha^{2} D_{\cU}^2  }{ \mu_c^2 \stepsize }  \notag \\
		&& \qquad - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } \Exp{\sqnorm{x^{t+1}-x^t }} + \frac{\stepsize}{2} \Exp{\sqnorm{g^t - \nabla F(x^t) }} ,
	\end{eqnarray*}
	where the second inequality uses boundedness of  $\cU$.
	%Define $\delta_t := \Exp{ F(x^t) - F(x^*) }$, $V_t : = \Exp{\sqnorm{g^t - \nabla F(x^t)}}$ , $R_t := \Exp{\sqnorm{x^{t+1} - x^t }}$. Then taking expectation, we have
	%\begin{eqnarray}\label{eq:descent_delta_conv} \delta_{t+1} \leq (1-  \alpha) \delta_t + \fr{ \alpha^{2} D_{\cU}^2 }{ \mu_c^2 \stepsize }   - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} } R_t + \frac{\stepsize}{2} V_t .\end{eqnarray}

	%\textbf{Step II. Controlling the error term of momentum $V_t$.} To control the error term in the above inequality, we use a recursive bound given by Lemma~\ref{le:key_HB_recursion}
%	\begin{eqnarray}\label{eq:HB_recursion} V_{t+1}  \leq (1 - \momentum) V_t  + \fr{3 L^2}{\momentum} R_t + \momentum^2 \sigma^2 . \end{eqnarray}

Summing up the inequality  above with a $\frac{\stepsize}{\momentum}$ multiple of the result of \Cref{le:key_HB_recursion}, we recognize the Lyapunov function $\Lambda_t^{\text{HB}} $ defined in \eqref{eq:Lyapunov_HB}, and derive
	\begin{eqnarray*}
		\Lambda_{t+1}^{\text{HB}} &\leq& \Lambda_t^{\text{HB}} -  \alpha \Exp{ F(x^t)  - F(x^*) }   - \frac{\stepsize}{2} \Exp{\sqnorm{g^t - \nabla F(x^t)}} \\
		&&\qquad  + \fr{ \alpha^{2} D_{\cU}^2 }{ \mu_c^2 \stepsize }   - \rb{ \fr{1}{2 \stepsize } - \fr{L}{2} - \frac{3 L^2 \stepsize }{\momentum^2} } \Exp{\sqnorm{x^{t+1}-x^t }} + \momentum \stepsize \sigma^2 \\
		&\leq& (1 -  \alpha) \Lambda_t^{\text{HB}} + \fr{ \alpha^{2} D_{\cU}^2 }{ \mu_c^2 \stepsize }  + \momentum \stepsize \sigma^2 ,
	\end{eqnarray*}
	where the last step holds for $ \alpha \leq \momentum / 2$ and $\stepsize \leq \frac{\momentum}{4 L}$. Unrolling the recursion from $t = 0$ to $t = T-1$ and choosing $\stepsize = \fr{\momentum}{ 4 L }$, we obtain
	\begin{eqnarray}
		\Lambda_{T}^{\text{HB}} &\leq& (1 -  \alpha )^T \Lambda_0^{\text{HB}}  + \fr{ \alpha D_{\cU}^2}{ \mu_c^2   \stepsize }   +  \fr{\momentum \stepsize  \sigma^2 }{  \alpha  } \notag \\
		&\leq& (1 -  \alpha )^T \Lambda_0^{\text{HB}}  + \fr{ 4 L  D_{\cU}^2  }{ \mu_c^2  } \frac{\alpha}{\momentum}  +  \fr{ \sigma^2 }{ 4 L   } \frac{\momentum^2}{\alpha} \leq \varepsilon  \notag ,
	\end{eqnarray}
	where the last inequality holds by setting $\alpha =  \min\left\{ \frac{\momentum}{2}, \frac{3 \mu_c^2   }{2 L D_{\cU}^2} \momentum \varepsilon , \frac{\sigma \mu_c }{4 L D_{\cU}} \beta^{\frac{3}{2}} \right\}$ , $\beta = \min\left\{1, \frac{\mu_c^2  }{9 D_{\cU}^2 \sigma^2} \varepsilon^2 \right\} $, and the number of iterations as 
	$$
	T = \frac{1}{ \alpha} \log\rb{\frac{3 \Lambda_0^{\text{HB}}}{\varepsilon} } = \wt \cO\rb{ \frac{L D_{\cU}^2 }{\mu_c^2  } \frac{1}{\varepsilon}  + \frac{ L D_{\cU}^4 \sigma^2 }{\mu_c^4 } \frac{1}{\varepsilon^3}  } .
	$$
\end{proof}

\begin{customproof}{\Cref{le:key_HB_recursion}}
		Using the update rule of $g^{t+1}$ and the unbiasedness of stochastic gradients, we have
  $$
		\begin{aligned}
			\mathbb{E}&\left[ \sqnorm{g^{t+1} - \nabla F(x^{t+1})} \right] 
			 =  \Exp{ \sqnorm{(1 - \momentum) g^{t} + \momentum \nabla f(x^{t+1}, \xi^{t+1}) - \nabla F(x^{t+1})}  } \notag \\
