\begin{lemma}[Lemma 2 in \cite{fatkhullin2023momentum}]\label{le:key_HB_recursion}
		Let $\momentum \in (0,1]$ and $g^t$ be updated via \eqref{eq:PSGDM_x_upd}. Then
		\begin{eqnarray}\notag %\label{eq:key_HB_recursion}
			\Exp{ \sqnorm{g^{t+1} - \nabla F(x^{t+1})} }  \leq (1 - \momentum) \Exp{ \sqnorm{  g^{t} - \nabla F(x^{t}) } }  + \fr{3 L^2}{\momentum} \Exp{ \sqnorm{  x^{t} - x^{t+1}  } } + \momentum^2 \sigma^2 .
		\end{eqnarray}
	\end{lemma}

\begin{lemma}\label{le:bregman_properties}
			Let $\phi(\cdot)$ be convex and for any $\stepsize>0$, $x\in \cX$, define $$x^{+} := \argmin_{y\in \cX} \left\{ \phi(y) + \fr{1}{2 \stepsize} \sqnorm{y - x} \right\}. $$ 
        Then
			$$
			\phi(y) + \fr{1}{2 \stepsize} \sqnorm{y - x} \geq \phi(x^{+}) + \fr{1}{2 \stepsize} \sqnorm{x^{+} - x }  + \fr{1}{2\stepsize} \sqnorm{ y  - x^{+} }  \quad \text{for all } y \in \cX. 
			$$\label{le:bregman_properties_optimality}
	\end{lemma}

